def transform(grid):
    # 1. Identify background
    bg = grid[0][0]

    # 2. Identify box markers (color with 4 corners)
    markers = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val != bg:
                if val not in markers:
                    markers[val] = []
                markers[val].append((r, c))

    box_color = None
    r_min, c_min = -1, -1
    r_max, c_max = -1, -1

    for val, coords in markers.items():
        if len(coords) >= 4:
            rs = {r for r, c in coords}
            cs = {c for r, c in coords}
            min_r, max_r = min(rs), max(rs)
            min_c, max_c = min(cs), max(cs)
            corners = [(min_r, min_c), (min_r, max_c), (max_r, min_c), (max_r, max_c)]
            corners_found = sum(1 for corner in corners if corner in coords)
            if corners_found == 4:
                box_color = val
                r_min, c_min, r_max, c_max = min_r, min_c, max_r, max_c
                break

    # 3. Collect non-bg, non-marker features
    features = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val != bg and val != box_color:
                features.append((r, c, val))

    features.sort(key=lambda x: (x[0], x[1]))

    # 4. Build Output
    h = r_max - r_min + 1
    w = c_max - c_min + 1
    output = [[bg] * w for _ in range(h)]

    # Corners
    output[0][0] = box_color
    output[0][w-1] = box_color
    output[h-1][0] = box_color
    output[h-1][w-1] = box_color

    idx = 0

    # Top (L->R)
    for i in range(1, h-1):
        if idx < len(features):
            output[0][i] = features[idx][2]
            idx += 1

    # Right (T->B)
    for i in range(1, h-1):
        if idx < len(features):
            output[i][w-1] = features[idx][2]
            idx += 1

    # Bottom (R->L)
    for i in range(w-2, 0, -1):
        if idx < len(features):
            output[h-1][i] = features[idx][2]
            idx += 1

    # Left (B->T)
    for i in range(h-2, 0, -1):
        if idx < len(features):
            output[i][0] = features[idx][2]
            idx += 1

    return output
